const
  RETRY_MAX_RETRIES = 4
  RETRY_BASE_DELAY_MS = 500
  RETRY_MAX_DELAY_MS = 30_000
  DEFAULT_API_BASE = ""

proc currentEnv(): Env =
  let forgeApiUrl = getEnv("FORGE_API_URL")
  let openaiBaseUrl = getEnv("OPENAI_BASE_URL")
  let forgeApiKey = getEnv("FORGE_API_KEY")
  let openaiApiKey = getEnv("OPENAI_API_KEY")
  result = Env(
    forgeApiUrl: if forgeApiUrl.len > 0: forgeApiUrl else: openaiBaseUrl,
    forgeApiKey: if forgeApiKey.len > 0: forgeApiKey else: openaiApiKey
  )

template ENV*: Env = currentEnv()

proc validateRole(role: Role) =
  if role notin ["system", "user", "assistant", "tool", "function", "developer"]:
    raise newException(ValueError, "Unsupported role: " & role)

proc isIdentifierChar(ch: char): bool =
  (ch >= 'a' and ch <= 'z') or
  (ch >= 'A' and ch <= 'Z') or
  (ch >= '0' and ch <= '9') or
  ch in {'_', '-', '.'}

proc validateIdentifier(value: string, fieldName: string) =
  let trimmed = value.strip()
  if trimmed.len == 0:
    raise newException(ValueError, fieldName & " must not be empty")
  for ch in trimmed:
    if not isIdentifierChar(ch):
      raise newException(ValueError, fieldName & " contains an invalid character")

proc stripTrailingSlashes(value: string): string =
  result = value
  while result.len > 0 and result[^1] == '/':
    result.setLen(result.len - 1)

proc resolveEndpointUrl(rawBaseUrl: string, endpointPath: string): string =
  let endpoint = endpointPath.strip(chars = {'/'})
  let raw = stripTrailingSlashes(rawBaseUrl.strip())
  let base = if raw.len > 0: raw else: DEFAULT_API_BASE
  if base.endsWith("/v1/" & endpoint) or base.endsWith("/" & endpoint):
    return base
  if base.endsWith("/v1"):
    return base & "/" & endpoint
  return base & "/v1/" & endpoint

proc resolveApiUrl(env: Env): string =
  resolveEndpointUrl(env.forgeApiUrl, "chat/completions")

proc resolveModelsUrl(env: Env): string =
  resolveEndpointUrl(env.forgeApiUrl, "models")

proc requireApiKey(env: Env): string =
  let key = env.forgeApiKey.strip()
  if key.len == 0:
    raise newException(ValueError, "forgeApiKey is not configured")
  result = key

proc initMessageImpl(role: Role, content: JsonNode, name: Option[string], toolCallId: Option[string], toolCalls: Option[seq[ToolCall]]): Message =
  validateRole(role)
  result = Message(role: role, content: content, name: name, tool_call_id: toolCallId, tool_calls: toolCalls)

proc initMessage*(role: Role, content: string, name: Option[string] = none(string), toolCallId: Option[string] = none(string), toolCalls: Option[seq[ToolCall]] = none(seq[ToolCall])): Message =
  initMessageImpl(role, %content, name, toolCallId, toolCalls)

proc initMessage*(role: Role, content: JsonNode, name: Option[string] = none(string), toolCallId: Option[string] = none(string), toolCalls: Option[seq[ToolCall]] = none(seq[ToolCall])): Message =
  initMessageImpl(role, content, name, toolCallId, toolCalls)

proc requireObject(node: JsonNode, path: string): JsonNode =
  if node == nil or node.kind != JObject:
    raise newException(ValueError, path & " must be an object")
  result = node

proc requireArray(node: JsonNode, path: string): JsonNode =
  if node == nil or node.kind != JArray:
    raise newException(ValueError, path & " must be an array")
  result = node

proc requireField(node: JsonNode, key: string, path: string): JsonNode =
  if node == nil or node.kind != JObject or not node.hasKey(key):
    raise newException(ValueError, path & "." & key & " is required")
  result = node[key]

proc requireString(node: JsonNode, path: string, allowEmpty = false): string =
  if node == nil or node.kind != JString:
    raise newException(ValueError, path & " must be a string")
  result = node.getStr()
  if not allowEmpty and result.len == 0:
    raise newException(ValueError, path & " must not be empty")

proc optionalString(node: JsonNode, path: string, allowEmpty = true): Option[string] =
  if node == nil or node.kind == JNull:
    return none(string)
  if node.kind != JString:
    raise newException(ValueError, path & " must be a string")
  let value = node.getStr()
  if not allowEmpty and value.len == 0:
    raise newException(ValueError, path & " must not be empty")
  some(value)

proc optionalBool(node: JsonNode, path: string): Option[bool] =
  if node == nil or node.kind == JNull:
    return none(bool)
  if node.kind != JBool:
    raise newException(ValueError, path & " must be a boolean")
  some(node.getBool())

proc requireInt(node: JsonNode, path: string): int =
  if node == nil or node.kind notin {JInt}:
    raise newException(ValueError, path & " must be an integer")
  result = node.getInt()

proc requireInt64(node: JsonNode, path: string): int64 =
  if node == nil or node.kind notin {JInt}:
    raise newException(ValueError, path & " must be an integer")
  result = node.getBiggestInt()

proc selectJsonAlias(primary: Option[JsonNode], secondary: Option[JsonNode], primaryName: string, secondaryName: string): Option[JsonNode] =
  if primary.isSome and secondary.isSome:
    let a = primary.get()
    let b = secondary.get()
    if a != b:
      raise newException(ValueError, primaryName & " and " & secondaryName & " were both provided with different values")
    return primary
  if primary.isSome:
    return primary
  return secondary

proc selectIntAlias(primary: Option[int], secondary: Option[int], primaryName: string, secondaryName: string): Option[int] =
  if primary.isSome and secondary.isSome:
    if primary.get() != secondary.get():
      raise newException(ValueError, primaryName & " and " & secondaryName & " were both provided with different values")
    return primary
  if primary.isSome:
    return primary
  return secondary

proc containsToolName(tools: seq[Tool], name: string): bool =
  for tool in tools:
    if tool.function.name == name:
      return true
  return false

proc validateToolCall(toolCall: ToolCall, path: string) =
  if toolCall.id.strip().len == 0:
    raise newException(ValueError, path & ".id must not be empty")
  if toolCall.`type` != "function":
    raise newException(ValueError, path & ".type must be 'function'")
  validateIdentifier(toolCall.function.name, path & ".function.name")

proc validateTool(tool: Tool, path: string) =
  if tool.`type` != "function":
    raise newException(ValueError, path & ".type must be 'function'")
  validateIdentifier(tool.function.name, path & ".function.name")
  if tool.function.parameters.isSome:
    let parameters = tool.function.parameters.get()
    if parameters != nil and parameters.kind != JObject:
      raise newException(ValueError, path & ".function.parameters must be a JSON object")

proc ensureArray(value: JsonNode): seq[JsonNode] =
  if value == nil or value.kind == JNull:
    return @[]
  case value.kind
  of JArray:
    for item in value:
      result.add(item)
  of JString, JObject:
    result.add(value)
  else:
    raise newException(ValueError, "Message content must be a string, an object, or an array of content parts")

proc normalizeContentPart(part: JsonNode): JsonNode =
  if part == nil or part.kind == JNull:
    raise newException(ValueError, "Content part must not be null")

  if part.kind == JString:
    return %*{"type": "text", "text": part.getStr()}

  let obj = requireObject(part, "content part")
  let t = requireString(requireField(obj, "type", "content part"), "content part.type")

  case t
  of "text":
    let textValue = requireString(requireField(obj, "text", "content part"), "content part.text", true)
    return %*{"type": "text", "text": textValue}
  of "image_url":
    let imageUrl = requireObject(requireField(obj, "image_url", "content part"), "content part.image_url")
    let url = requireString(requireField(imageUrl, "url", "content part.image_url"), "content part.image_url.url")
    var normalizedImageUrl = %*{"url": url}
    if imageUrl.hasKey("detail"):
      let detail = optionalString(imageUrl["detail"], "content part.image_url.detail", false)
      if detail.isSome:
        normalizedImageUrl["detail"] = %detail.get()
    return %*{"type": "image_url", "image_url": normalizedImageUrl}
  of "file_url":
    let fileUrl = requireObject(requireField(obj, "file_url", "content part"), "content part.file_url")
    let url = requireString(requireField(fileUrl, "url", "content part.file_url"), "content part.file_url.url")
    var normalizedFileUrl = %*{"url": url}
    if fileUrl.hasKey("mime_type"):
      let mimeType = optionalString(fileUrl["mime_type"], "content part.file_url.mime_type", false)
      if mimeType.isSome:
        normalizedFileUrl["mime_type"] = %mimeType.get()
    return %*{"type": "file_url", "file_url": normalizedFileUrl}
  else:
    raise newException(ValueError, "Unsupported message content part type: " & t)

proc normalizeStructuredContent(content: JsonNode): JsonNode =
  let parts = ensureArray(content)
  if parts.len == 0:
    raise newException(ValueError, "Message content must not be empty")

  var normalizedParts = newJArray()
  for part in parts:
    normalizedParts.add(normalizeContentPart(part))

  if normalizedParts.len == 1 and normalizedParts[0].kind == JObject and normalizedParts[0].hasKey("type") and normalizedParts[0]["type"].getStr() == "text":
    return %normalizedParts[0]["text"].getStr()

  result = normalizedParts

proc normalizeToolCalls(toolCalls: seq[ToolCall]): JsonNode =
  var arr = newJArray()
  for index, toolCall in toolCalls:
    validateToolCall(toolCall, "tool_calls[" & $index & "]")
    arr.add(%*{
      "id": toolCall.id,
      "type": toolCall.`type`,
      "function": {
        "name": toolCall.function.name,
        "arguments": toolCall.function.arguments
      }
    })
  result = arr

proc normalizeMessage(message: Message): JsonNode =
  validateRole(message.role)

  if message.tool_call_id.isSome and message.role != "tool":
    raise newException(ValueError, "tool_call_id is only valid for tool messages")

  if message.role == "tool" and message.tool_call_id.isNone:
    raise newException(ValueError, "tool messages require tool_call_id")

  if message.tool_calls.isSome and message.role != "assistant":
    raise newException(ValueError, "tool_calls are only valid for assistant messages")

  if message.name.isSome:
    if message.role notin ["system", "user", "assistant", "developer", "function"]:
      raise newException(ValueError, "name is not supported for role '" & message.role & "'")
    if message.name.get().strip().len == 0:
      raise newException(ValueError, "name must not be empty")

  if message.role == "function" and message.name.isNone:
    raise newException(ValueError, "function messages require name")

  result = newJObject()
  result["role"] = %message.role

  if message.name.isSome:
    result["name"] = %message.name.get().strip()

  if message.tool_call_id.isSome:
    result["tool_call_id"] = %message.tool_call_id.get().strip()

  if message.tool_calls.isSome:
    result["tool_calls"] = normalizeToolCalls(message.tool_calls.get())

  if message.content == nil or message.content.kind == JNull:
    if message.role == "assistant" and message.tool_calls.isSome:
      result["content"] = newJNull()
      return
    raise newException(ValueError, "Message content must not be null for role '" & message.role & "'")

  if message.role in ["tool", "function"]:
    result["content"] = message.content
    return

  result["content"] = normalizeStructuredContent(message.content)

proc normalizeToolChoice(toolChoice: Option[JsonNode], tools: Option[seq[Tool]]): JsonNode =
  if toolChoice.isNone or toolChoice.get() == nil or toolChoice.get().kind == JNull:
    return nil

  let availableTools = if tools.isSome: tools.get() else: @[]
  let tc = toolChoice.get()

  if tc.kind == JString:
    let value = tc.getStr()
    if value in ["none", "auto"]:
      return %value
    if value == "required":
      if availableTools.len == 0:
        raise newException(ValueError, "tool_choice 'required' was provided but no tools were configured")
      return %"required"
    raise newException(ValueError, "Unsupported tool_choice value: " & value)

  if tc.kind != JObject:
    raise newException(ValueError, "tool_choice must be a string or an object")

  let obj = tc

  if obj.hasKey("name"):
    let name = requireString(obj["name"], "tool_choice.name")
    if availableTools.len == 0 or not containsToolName(availableTools, name):
      raise newException(ValueError, "tool_choice references an unknown tool: " & name)
    return %*{"type": "function", "function": {"name": name}}

  let selectorType = requireString(requireField(obj, "type", "tool_choice"), "tool_choice.type")
  if selectorType != "function":
    raise newException(ValueError, "tool_choice.type must be 'function'")

  let fnObj = requireObject(requireField(obj, "function", "tool_choice"), "tool_choice.function")
  let name = requireString(requireField(fnObj, "name", "tool_choice.function"), "tool_choice.function.name")
  if availableTools.len == 0 or not containsToolName(availableTools, name):
    raise newException(ValueError, "tool_choice references an unknown tool: " & name)

  result = %*{"type": "function", "function": {"name": name}}

proc buildJsonSchemaObject(schemaNode: JsonNode, path: string): JsonNode =
  let obj = requireObject(schemaNode, path)
  let name = requireString(requireField(obj, "name", path), path & ".name")
  let schema = requireField(obj, "schema", path)
  if schema.kind != JObject:
    raise newException(ValueError, path & ".schema must be a JSON object")

  var jsonSchemaObj = newJObject()
  jsonSchemaObj["name"] = %name
  jsonSchemaObj["schema"] = schema

  if obj.hasKey("strict"):
    let strictValue = optionalBool(obj["strict"], path & ".strict")
    if strictValue.isSome:
      jsonSchemaObj["strict"] = %strictValue.get()

  result = jsonSchemaObj

proc normalizeResponseFormat(
    responseFormat: Option[JsonNode],
    response_format: Option[JsonNode],
    outputSchema: Option[JsonNode],
    output_schema: Option[JsonNode]
): JsonNode =
  let explicitFormat = selectJsonAlias(responseFormat, response_format, "responseFormat", "response_format")
  let schemaOpt = selectJsonAlias(outputSchema, output_schema, "outputSchema", "output_schema")

  let explicitPresent = explicitFormat.isSome and explicitFormat.get() != nil and explicitFormat.get().kind != JNull
  let schemaPresent = schemaOpt.isSome and schemaOpt.get() != nil and schemaOpt.get().kind != JNull

  if explicitPresent and schemaPresent:
    raise newException(ValueError, "responseFormat/response_format and outputSchema/output_schema cannot be used together")

  if explicitPresent:
    let ef = requireObject(explicitFormat.get(), "responseFormat")
    let formatType = requireString(requireField(ef, "type", "responseFormat"), "responseFormat.type")
    case formatType
    of "text", "json_object":
      return %*{"type": formatType}
    of "json_schema":
      let schemaField = requireField(ef, "json_schema", "responseFormat")
      return %*{"type": "json_schema", "json_schema": buildJsonSchemaObject(schemaField, "responseFormat.json_schema")}
    else:
      raise newException(ValueError, "Unsupported responseFormat.type: " & formatType)

  if not schemaPresent:
    return nil

  return %*{"type": "json_schema", "json_schema": buildJsonSchemaObject(schemaOpt.get(), "outputSchema")}

proc parseRetryAfter(value: string): Option[int] =
  let trimmed = value.strip()
  if trimmed.len == 0:
    return none(int)
  try:
    let seconds = parseFloat(trimmed)
    if seconds >= 0.0 and seconds < 100000000.0:
      return some(int(seconds * 1000.0))
  except ValueError:
    discard
  for fmt in ["ddd, dd MMM yyyy HH:mm:ss 'GMT'", "ddd, d MMM yyyy HH:mm:ss 'GMT'", "yyyy-MM-dd'T'HH:mm:ss'Z'"]:
    try:
      let dt = parse(trimmed, fmt, utc())
      let diff = int((dt.toTime() - getTime()).inMilliseconds)
      return some(max(0, diff))
    except CatchableError:
      discard
  return none(int)

proc computeBackoffDelay(attempt: int, retryAfterMs: Option[int] = none(int)): int =
  let exponentialDelay = min(float(RETRY_BASE_DELAY_MS) * pow(2.0, float(attempt)), float(RETRY_MAX_DELAY_MS))
  let deterministicJitter = 0.5 + (float(((attempt + 1) * 997) mod 1000) / 2000.0)
  let jitteredDelay = exponentialDelay * deterministicJitter
  if retryAfterMs.isSome:
    return int(max(jitteredDelay, float(retryAfterMs.get())))
  result = int(jitteredDelay)

proc isOk(code: HttpCode): bool =
  code.int in 200 .. 299

proc isRetryableStatus(code: HttpCode): bool =
  code.int in [408, 409, 425, 429, 500, 502, 503, 504]

proc isRetryableMethod(httpMethod: HttpMethod): bool =
  httpMethod in {HttpGet, HttpHead, HttpOptions}

proc fetchWithBackoff(
    url: string,
    httpMethod: HttpMethod,
    headers: HttpHeaders,
    body: string
): Future[HttpResponse] {.async.} =
  var lastException: ref CatchableError = nil
  let allowRetry = isRetryableMethod(httpMethod)
  let client = newAsyncHttpClient()

  try:
    for attempt in 0 .. RETRY_MAX_RETRIES:
      try:
        let resp = await client.request(url, httpMethod = httpMethod, body = body, headers = headers)
        let statusCode = resp.code

        if allowRetry and attempt < RETRY_MAX_RETRIES and isRetryableStatus(statusCode):
          var retryAfterMs = none(int)
          if resp.headers.hasKey("retry-after"):
            retryAfterMs = parseRetryAfter(resp.headers["retry-after"])
          await sleepAsync(computeBackoffDelay(attempt, retryAfterMs))
          continue

        let respBody = await resp.body
        return HttpResponse(status: statusCode, headers: resp.headers, body: respBody)
      except CatchableError as e:
        lastException = e
        if not allowRetry or attempt == RETRY_MAX_RETRIES:
          raise e
        await sleepAsync(computeBackoffDelay(attempt))
  finally:
    try:
      client.close()
    except CatchableError:
      discard

  if lastException != nil:
    raise lastException
  raise newException(IOError, "LLM request failed after exhausting retries")

proc parseToolCallNode(node: JsonNode, path: string): ToolCall =
  let obj = requireObject(node, path)
  result.id = requireString(requireField(obj, "id", path), path & ".id")
  result.`type` = requireString(requireField(obj, "type", path), path & ".type")
  if result.`type` != "function":
    raise newException(ValueError, path & ".type must be 'function'")
  let fnObj = requireObject(requireField(obj, "function", path), path & ".function")
  result.function.name = requireString(requireField(fnObj, "name", path & ".function"), path & ".function.name")
  result.function.arguments = requireString(requireField(fnObj, "arguments", path & ".function"), path & ".function.arguments", true)

proc toInvokeResult(node: JsonNode): InvokeResult =
  let root = requireObject(node, "response")
  result.id = requireString(requireField(root, "id", "response"), "response.id")
  result.created = requireInt64(requireField(root, "created", "response"), "response.created")
  result.model = requireString(requireField(root, "model", "response"), "response.model")

  let choicesNode = requireArray(requireField(root, "choices", "response"), "response.choices")
  result.choices = @[]
  for idx, item in choicesNode:
    let choicePath = "response.choices[" & $idx & "]"
    let choiceObj = requireObject(item, choicePath)
    var choice: Choice
    choice.index = requireInt(requireField(choiceObj, "index", choicePath), choicePath & ".index")

    if choiceObj.hasKey("finish_reason") and choiceObj["finish_reason"].kind != JNull:
      choice.finish_reason = some(requireString(choiceObj["finish_reason"], choicePath & ".finish_reason", true))

    let messageObj = requireObject(requireField(choiceObj, "message", choicePath), choicePath & ".message")
    choice.message.role = requireString(requireField(messageObj, "role", choicePath & ".message"), choicePath & ".message.role")
    validateRole(choice.message.role)

    let hasContent = messageObj.hasKey("content")
    let hasToolCalls = messageObj.hasKey("tool_calls") and messageObj["tool_calls"].kind != JNull

    if not hasContent and not hasToolCalls:
      raise newException(ValueError, choicePath & ".message must contain content or tool_calls")

    if hasContent:
      choice.message.content = messageObj["content"]
    else:
      choice.message.content = newJNull()

    if hasToolCalls:
      let toolCallsNode = requireArray(messageObj["tool_calls"], choicePath & ".message.tool_calls")
      var calls: seq[ToolCall] = @[]
      for tcIndex, tcNode in toolCallsNode:
        calls.add(parseToolCallNode(tcNode, choicePath & ".message.tool_calls[" & $tcIndex & "]"))
      choice.message.tool_calls = some(calls)

    result.choices.add(choice)

  if root.hasKey("usage") and root["usage"].kind != JNull:
    let usageObj = requireObject(root["usage"], "response.usage")
    result.usage = some(UsageInfo(
      prompt_tokens: requireInt(requireField(usageObj, "prompt_tokens", "response.usage"), "response.usage.prompt_tokens"),
      completion_tokens: requireInt(requireField(usageObj, "completion_tokens", "response.usage"), "response.usage.completion_tokens"),
      total_tokens: requireInt(requireField(usageObj, "total_tokens", "response.usage"), "response.usage.total_tokens")
    ))

proc invokeLLM*(params: InvokeParams, env: Env): Future[InvokeResult] {.async.} =
  let apiKey = requireApiKey(env)

  if params.messages.len == 0:
    raise newException(ValueError, "messages must not be empty")

  if params.model.isNone:
    raise newException(ValueError, "model is required")

  let modelName = params.model.get().strip()
  if modelName.len == 0:
    raise newException(ValueError, "model must not be empty")

  let resolvedMaxTokens = selectIntAlias(params.maxTokens, params.max_tokens, "maxTokens", "max_tokens")
  if resolvedMaxTokens.isSome and resolvedMaxTokens.get() <= 0:
    raise newException(ValueError, "max_tokens must be greater than zero")

  let selectedToolChoice = selectJsonAlias(params.toolChoice, params.tool_choice, "toolChoice", "tool_choice")

  let thinkingPresent = params.thinking.isSome and params.thinking.get() != nil and params.thinking.get().kind != JNull
  let reasoningPresent = params.reasoning.isSome and params.reasoning.get() != nil and params.reasoning.get().kind != JNull
  if thinkingPresent and reasoningPresent:
    raise newException(ValueError, "thinking and reasoning cannot both be set")

  var payload = newJObject()
  payload["model"] = %modelName

  var messagesArr = newJArray()
  for msg in params.messages:
    messagesArr.add(normalizeMessage(msg))
  payload["messages"] = messagesArr

  if params.tools.isSome:
    let toolsSeq = params.tools.get()
    if toolsSeq.len > 0:
      var toolsArr = newJArray()
      for idx, t in toolsSeq:
        validateTool(t, "tools[" & $idx & "]")
        var tObj = %*{"type": t.`type`}
        var fnObj = %*{"name": t.function.name}
        if t.function.description.isSome:
          fnObj["description"] = %t.function.description.get()
        if t.function.parameters.isSome and t.function.parameters.get() != nil:
          fnObj["parameters"] = t.function.parameters.get()
        tObj["function"] = fnObj
        toolsArr.add(tObj)
      payload["tools"] = toolsArr

  let normalizedToolChoice = normalizeToolChoice(selectedToolChoice, params.tools)
  if normalizedToolChoice != nil:
    payload["tool_choice"] = normalizedToolChoice

  if resolvedMaxTokens.isSome:
    payload["max_tokens"] = %resolvedMaxTokens.get()

  if thinkingPresent:
    payload["thinking"] = params.thinking.get()

  if reasoningPresent:
    payload["reasoning"] = params.reasoning.get()

  let normalizedResponseFormat = normalizeResponseFormat(
    params.responseFormat,
    params.response_format,
    params.outputSchema,
    params.output_schema
  )
  if normalizedResponseFormat != nil:
    payload["response_format"] = normalizedResponseFormat

  let headers = newHttpHeaders({
    "content-type": "application/json",
    "authorization": "Bearer " & apiKey
  })

  let response = await fetchWithBackoff(resolveApiUrl(env), HttpPost, headers, $payload)

  if not isOk(response.status):
    raise newException(IOError, "LLM invoke failed: " & $response.status & " – " & response.body)

  let jsonResult = parseJson(response.body)
  result = toInvokeResult(jsonResult)

proc invokeLLM*(params: InvokeParams): Future[InvokeResult] {.async.} =
  result = await invokeLLM(params, currentEnv())

proc listLLMModels*(env: Env): Future[ModelsResponse] {.async.} =
  let apiKey = requireApiKey(env)
  let headers = newHttpHeaders({
    "authorization": "Bearer " & apiKey
  })

  let response = await fetchWithBackoff(resolveModelsUrl(env), HttpGet, headers, "")

  if not isOk(response.status):
    raise newException(IOError, "List LLM models failed: " & $response.status & " – " & response.body)

  let jsonResult = requireObject(parseJson(response.body), "models response")
  result.`object` = requireString(requireField(jsonResult, "object", "models response"), "models response.object")

  let dataNode = requireArray(requireField(jsonResult, "data", "models response"), "models response.data")
  result.data = @[]
  for idx, item in dataNode:
    let itemPath = "models response.data[" & $idx & "]"
    let obj = requireObject(item, itemPath)
    result.data.add(ModelInfo(
      id: requireString(requireField(obj, "id", itemPath), itemPath & ".id"),
      `object`: requireString(requireField(obj, "object", itemPath), itemPath & ".object"),
      created: requireInt64(requireField(obj, "created", itemPath), itemPath & ".created"),
      owned_by: requireString(requireField(obj, "owned_by", itemPath), itemPath & ".owned_by")
    ))

proc listLLMModels*(): Future[ModelsResponse] {.async.} =
  result = await listLLMModels(currentEnv())
